// CDL3STARSINSOUTHLookback returns how many leading bars
// [Core.CDL3STARSINSOUTH] consumes before its first value: called with startIdx
// 0, its first value is at that bar.
func (c *Core) CDL3STARSINSOUTHLookback() (int, error) {
	lookback := c.cdl3starsinsouthLookback()
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

